// Category A (overlay) — behavior borrowed from react-aria-components, look owned in src.
import {
  Dialog,
  DialogTrigger as AriaDialogTrigger,
  Popover as AriaPopover,
} from "react-aria-components";
import type {
  DialogTriggerProps as AriaDialogTriggerProps,
  PopoverProps as AriaPopoverProps,
} from "react-aria-components";
import type { ReactNode, Ref } from "react";
import { resolveOffset } from "./resolveOffset";
import "./Popover.css";

export interface PopoverTriggerProps extends AriaDialogTriggerProps {}

export function PopoverTrigger(props: PopoverTriggerProps) {
  return <AriaDialogTrigger {...props} />;
}

// There is deliberately NO `surface` prop. The overlay layer's treatment — opaque or frosted — is
// the THEME'S (`<html data-surface="translucent">`), and this component reads it and nothing else.
// A panel whose legibility must win outright needs no exception: the translucent surface's opacity
// is DERIVED as the least opaque step at which text · text-muted · text-brand all still clear 4.5:1
// composited over pure black AND pure white, so a frosted panel is legible over any backdrop by
// construction. An exception could only buy what ADR-0022 removes: one app shipping some frosted
// overlays and some solid ones. That matters most here:
// every anchored overlay (Menu · Select · ComboBox · DatePicker · ColorPicker) routes through this
// component, so a per-instance hatch here is a per-instance hatch on all of them.
export interface PopoverContentProps
  extends Omit<AriaPopoverProps, "className" | "children"> {
  /**
   * Surface tier — padding and radius move together, so the panel stays concentric
   * with whatever sits inside it.
   *
   * `small` is for the collection dropdowns (Menu, Select, ComboBox), which also pass
   * `noDialog`. That pairing is not a convention you can drift from: `usage-invariant:check`
   * enforces it both ways. Anything else — DatePicker, ColorPicker, an arbitrary panel —
   * takes the default.
   *
   * @usageInvariant popover-size-nodialog
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /**
   * Skip the Dialog wrapper — for collections that already manage their own focus and
   * roving tabindex (`<Menu>`, `<ListBox>`). Those carry role=menu/listbox already, so a
   * Dialog around them stacks a second focus manager on the first. Arbitrary content
   * (a Calendar, a colour panel) takes the default and stays wrapped. Same split as RAC's
   * own convention.
   *
   * Caution — this does **not** remove `role="dialog"` itself. RAC decides that on the
   * popover container from `!isNonModal || trigger === "SubmenuTrigger"` (Popover.mjs),
   * and `isNonModal` comes from the parent through PopoverContext. Only ComboBox passes
   * `isNonModal: true`, so only its container has no role. Select and MenuTrigger do not,
   * so theirs keep role=dialog — the same result as RAC's own `<Popover><ListBox>` example.
   * Forcing `isNonModal` here would switch off focus containment and dismiss handling with
   * it, so we leave it alone.
   *
   * Absent = wrapped.
   */
  noDialog?: boolean;
  /**
   * Floor the panel at its TRIGGER's width — for a panel whose content is a list of choices the
   * trigger already displays one of.
   *
   * Opt-in rather than the default, because the panel's own rule is to hug: a Calendar, a colour
   * panel or arbitrary content sizes to itself and has no reason to inherit a trigger's width.
   * It is a `min` and never a fixed width, so a long option still widens the panel past the
   * trigger rather than truncating — the narrow case already worked and must keep working.
   *
   * The width arrives as React Aria's own injected `--trigger-width` on this element, which
   * `component-contract.md` §6 carve-out 2 sanctions consuming by name for exactly this.
   *
   * Absent = the panel hugs its content.
   */
  matchTriggerWidth?: boolean;
  /** Panel content. */
  children?: ReactNode;
  /** Extra class (optional). `sd-popover__content` is always kept. */
  className?: string;
  /** Forwarded to the underlying popover DOM node. */
  ref?: Ref<HTMLElement>;
}

export function PopoverContent({
  size = "medium",
  noDialog,
  matchTriggerWidth,
  children,
  className,
  ref,
  offset,
  ...props
}: PopoverContentProps) {
  return (
    <AriaPopover
      {...props}
      ref={ref}
      offset={offset ?? resolveOffset("--sd-popover-content-offset")}
      // No `data-surface` here, at all: the only `[data-surface]` in the system is the one on
      // <html>, which swaps the Sys tokens this panel's background relay reads. Emitting one on the
      // panel would shadow the theme for that instance — the escape hatch this component no longer
      // offers (see the note above the props).
      data-size={size}
      data-match-trigger-width={matchTriggerWidth || undefined}
      className={className ? `sd-popover__content ${className}` : "sd-popover__content"}
    >
      {noDialog ? children : <Dialog className="sd-popover__dialog">{children}</Dialog>}
    </AriaPopover>
  );
}

/* Popover.css — .sd-popover__* (포털 오버레이)
   규칙: sd- 프리픽스 / 평평한 단일 클래스 / 상태는 react-aria data-* / Cmp 토큰 참조. */
.sd-popover__content {
  /* No min/max width BY DEFAULT — the popover hugs its content freely (calendars and panels size
     to their own content, not the trigger). RAC sets an inline max-height so it never exceeds the
     space to the viewport edge; scroll longer content inside the bordered box.
     The one departure is opt-in and is the rule below. */
  overflow: auto;
  /* Surface treatment — the panel's paper and its blur, read straight from the THEME and from
     nothing else. `--sd-popover-content-background` / `-backdrop-filter` are this component's relays
     for the Sys `surface-treatment.overlay-*` pair, which `[data-surface]` on <html> swaps
     (tokens.css). Under a standard theme they resolve to what this panel painted before ADR-0022 —
     the opaque overlay surface and `none`, `backdrop-filter`'s initial value, which creates no
     backdrop root.
     Frosted glass used to be a per-CALL-SITE choice (this file only styled `[data-variant]` and the
     tsx defaulted to `standard`), so one app could ship some frosted popovers and some solid ones.
     Glass is the third element of elevation, alongside surface lightness and shadow — a system
     property — so the theme owns it outright and no instance may depart (see below the size rules).
     -webkit- prefix for Safari, which shipped the prefixed form long before the unprefixed one. */
  background: var(--sd-popover-content-background);
  -webkit-backdrop-filter: var(--sd-popover-content-backdrop-filter);
  backdrop-filter: var(--sd-popover-content-backdrop-filter);
  color: var(--sd-popover-content-foreground);
  border: var(--sd-popover-content-border-width) solid var(--sd-popover-content-border);
  border-radius: var(--sd-popover-content-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  box-shadow: var(--sd-popover-content-shadow);
  padding: var(--sd-popover-content-padding-current);
}

/* A panel that lists the choices its trigger displays one of is floored at the TRIGGER's width, so
   the open list reads as belonging to the closed control rather than as a small card under its left
   corner. `--trigger-width` is React Aria's own, injected on this element, and §6 carve-out 2
   sanctions consuming it by name. Without it a Select with a 1072px trigger opens a 127px panel.
   `min`, not `width`: a long option still widens the panel past the trigger. */
.sd-popover__content[data-match-trigger-width] {
  min-inline-size: var(--trigger-width);
}

/* size → the matching surface tier (padding + radius paired, concentric). Shadow is
   NOT on this axis: every anchored overlay floats at the same prominence (elevation.high),
   so a compact Menu reads as elevated as a large panel. */
.sd-popover__content[data-size="small"] {
  --sd-popover-content-padding-current: var(--sd-popover-content-padding-small);
  --sd-popover-content-radius-current: var(--sd-popover-content-radius-small);
}
.sd-popover__content[data-size="medium"] {
  --sd-popover-content-padding-current: var(--sd-popover-content-padding-medium);
  --sd-popover-content-radius-current: var(--sd-popover-content-radius-medium);
}
.sd-popover__content[data-size="large"] {
  --sd-popover-content-padding-current: var(--sd-popover-content-padding-large);
  --sd-popover-content-radius-current: var(--sd-popover-content-radius-large);
}

/* No `[data-surface]` rule on this panel — deliberately. The only `[data-surface]` in the system is
   the one on <html> (tokens.css), which swaps the Sys pair the base rule above already reads. A
   per-instance departure would serve two cases, and both are closed. `standard` ("this panel's
   legibility must win outright") is never needed: the
   translucent surface's opacity is DERIVED as the least opaque step at which text, text-muted and
   text-brand all still clear 4.5:1 composited over pure black AND pure white (plan-color.mjs § the
   translucent overlay surface), so a frosted panel is legible over any backdrop by construction, and
   stays legible where `backdrop-filter` is unsupported (the filter is the enhancement, the surface
   carries the contract). `translucent` under a solid theme is just the mixed-overlay incoherence
   ADR-0022 removes. It matters most here of the three: every anchored overlay (Menu · Select ·
   ComboBox · DatePicker · ColorPicker) paints through this class, so one hatch here is a hatch on
   all of them. A consumer who needs one panel to disagree owns this copied file. */

.sd-popover__content[data-entering] {
  animation: sd-popover-enter var(--sd-popover-animation-duration) var(--sd-easing-decelerate);
}

.sd-popover__content[data-exiting] {
  animation: sd-popover-exit var(--sd-popover-animation-duration) var(--sd-easing-accelerate);
}

.sd-popover__dialog {
  outline: none;
}

@keyframes sd-popover-enter {
  from {
    opacity: 0;
    transform: translateY(var(--sd-popover-content-translate-enter));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sd-popover-exit {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(var(--sd-popover-content-translate-exit));
  }
}

@media (prefers-reduced-motion: reduce) {
  .sd-popover__content[data-entering],
  .sd-popover__content[data-exiting] {
    animation: none;
  }
}
